using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Scenarios;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline loads two collections in one query (Cartesian explosion); Optimized
// calls the agent-owned SplitQuerySolution.Run. Do not edit this file — edit
// Scenarios/SplitQuery.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class SplitQueryBenchmark
{
    private SqliteConnection _connection = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using var db = AppDbContext.Create(_connection);
        db.Database.EnsureCreated();
        SeedData.SeedBlogs(db, blogs: 100, postsPerBlog: 30, contributorsPerBlog: 30);

        EquivalenceGuard.SameResults(Baseline(), Optimized(), b => b.Name);
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<BlogWithChildren> Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        var blogs = db.Blogs.Include(b => b.Posts).Include(b => b.Contributors).ToList();
        return blogs.Select(b => new BlogWithChildren(b.Name, b.Posts.Count, b.Contributors.Count)).ToList();
    }

    [Benchmark]
    public List<BlogWithChildren> Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        return SplitQuerySolution.Run(db);
    }
}
